TLM.f("Sancti/07-22",{"officium":"S. Mariæ Magdalenæ Pœnitentis","rule":["vide C7;","Gloria","CredoDA"],"ruleInherited":["Psalmi Dominica","Antiphonas horas"],"fallback":"Commune/C7","sections":{"Introitus":[{"k":"ref","la":"Ps 118:95-96"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"},{"k":"ref","la":"Ps 118:1"},{"k":"text","la":"Beáti immaculáti in via: qui ámbulant in lege Dómini."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Me exspectavérunt peccatóres, ut pérderent me: testimónia tua, Dómine, intelléxi: omnis consummatiónis vidi finem: latum mandátum tuum nimis. (Allelúja, allelúja.)"}],"Oratio":[{"k":"text","la":"Beátæ Maríæ Magdalénæ, quǽsumus, Dómine, suffrágiis adjuvémur: cujus précibus exorátus, quatriduánum fratrem Lázarum vivum ab ínferis resuscitásti:"},{"k":"macro","name":"Qui vivis"}],"Lectio":[{"k":"text","la":"Léctio libri Sapiéntiæ"},{"k":"ref","la":"Cant 3:2-5; 8:6-7"},{"k":"text","la":"Surgam, et circuíbo civitátem: per vicos et pláteas quæram, quem díligit ánima mea: quæsívi illum, et non invéni. Invenérunt me vígiles, qui custódiunt civitátem. Num quem díligit ánima mea, vidístis? Páululum cum pertransíssem eos, invéni, quem díligit ánima mea: ténui eum, nec dimíttam, donec introdúcam illum in domum matris meæ et in cubículum genetrícis meæ. Adjúro vos, fíliæ Jerúsalem, per cápreas cervósque campórum, ne suscitétis neque evigiláre faciátis diléctam, donec ipsa velit. Pone me ut signáculum super cor tuum, ut signáculum super bráchium tuum: quia fortis est ut mors diléctio, dura sicut inférnus æmulátio: lámpades ejus lámpades ignis atque flammárum. Aquæ multæ non potuérunt exstínguere caritátem, nec flúmina óbruent illam: si déderit homo omnem substántiam domus suæ pro dilectióne, quasi nihil despíciet eam."}],"Graduale":[{"k":"ref","la":"Ps 44:8"},{"k":"text","la":"Dilexísti justítiam, et odísti iniquitátem."},{"k":"text","la":"Proptérea unxit te Deus, Deus tuus, óleo lætítiæ.","mark":"V"},{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 44:3"},{"k":"text","la":"Diffúsa est grátia in lábiis tuis: proptérea benedíxit te Deus in ætérnum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 7:36-50"},{"k":"text","la":"In illo témpore: Rogábat Jesum quidam de pharisǽis, ut manducáret cum illo. Et ingréssus domum pharisǽi, discúbuit. Et ecce múlier, quæ erat in civitáte peccátrix, ut cognóvit, quod accubuísset in domo pharisǽi, áttulit alabástrum unguénti: et stans retro secus pedes ejus, lácrimis cœpit rigáre pedes ejus, et capíllis cápitis sui tergébat, et osculabátur pedes ejus, et unguénto ungébat. Videns autem pharisǽus, qui vocáverat eum, ait intra se, dicens: Hic si esset Prophéta, sciret útique, quæ et qualis est múlier, quæ tangit eum: quia peccátrix est. Et respóndens Jesus, dixit ad illum: Simon, hábeo tibi áliquid dícere. At ille ait: Magíster, dic. Duo debitóres erant cuidam fœneratóri: unus debébat denários quingéntos, et álius quinquagínta. Non habéntibus illis, unde rédderent, donávit utrísque. Quis ergo eum plus díligit? Respóndens Simon, dixit: Æstimo, quia is, cui plus donávit. At ille dixit ei: Recte judicásti. Et convérsus ad mulíerem, dixit Simóni: Vides hanc mulíerem? Intrávi in domum tuam, aquam pédibus meis non dedísti: hæc autem lácrimis rigávit pedes meos et capíllis suis tersit. Osculum mihi non dedísti: hæc autem, ex quo intrávit, non cessávit osculári pedes meos. Oleo caput meum non unxísti: hæc autem unguénto unxit pedes meos. Propter quod dico tibi:Remittúntur ei peccáta multa, quóniam diléxit multum. Cui autem minus dimíttitur, minus díligit. Dixit autem ad illam: Remittúntur tibi peccáta. Et cœpérunt, qui simul accumbébant, dícere intra se: Quis est hic, qui étiam peccáta dimíttit? Dixit autem ad mulíerem: Fides tua te salvam fecit: vade in pace."}],"Offertorium":[{"k":"ref","la":"Ps 44:10"},{"k":"text","la":"Fíliæ regum in honóre tuo, ástitit regína a dextris tuis in vestítu deauráto, circúmdata varietáte. (Allelúja.)"}],"Secreta":[{"k":"text","la":"Múnera nostra, quǽsumus. Dómine, beátæ Maríæ Magdalénæ gloriósa mérita tibi reddant accépta: cujus oblatiónis obséquium unigénitus Fílius tuus cleménter suscépit impénsum:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Ps 118:121; 118:122; 118:128"},{"k":"text","la":"Feci judícium et justítiam, Dómine, non calumniéntur mihi supérbi: ad ómnia mandáta tua dirigébar, omnem viam iniquitátis ódio hábui. (Allelúja.)"}],"Postcommunio":[{"k":"text","la":"Sumpto, quǽsumus, Dómine, único ac salutári remédio, Córpore et Sánguine tuo pretióso: ab ómnibus malis, sanctæ Maríæ Magdalénæ patrocíniis, eruámur:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"9f9c6ab7f4db3841":{"t":"Ps 118, 95-96, Ps 118, 1\n(Ps 118, 95-96) Na mene su vrebali grješnici da me upropaste, ali ja pazim na naredbe tvoje. Vidim da svršava sve, ma bilo ne znam kako veliko. Samo je tvoja zapovijed beskrajno uzvišena. (Ps 118, 1) Blago neokaljanima na životnom putu, koji žive po zakonu Gospodnjemu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 118, 95-96) Na mene su vrebali grješnici da me upropaste, ali ja pazim na naredbe tvoje. Vidim da svršava sve, ma bilo ne znam kako veliko. Samo je tvoja zapovijed beskrajno uzvišena.","kn":"(Ps. 118, 95, 96). Na mene vrebaju grješnici, da me upropaste, a ja razmišljam Tvoj zako-n. Gospodine! Vidjeh, da ima svršetak sve, ma kako bilo veliko, samo je zakon Tvoj neizmjeran i bez kraja-. (Aleluja. Aleluja). (Ps. 118, 1). Blago onima, koji su čista života, koji žive po zakonu Gospodnjem! Slava Ocu. Na mene.","knRef":"Kniewald 1942, str. 822–823 (snimka 412) (OCR)"},"4bcbc8a1626e6d2c":{"t":"<i>Pomolimo se</i>.\nPomogao nam, molimo, Gospodine, zagovor blažene Marije Magdalene, čijim si molbama potaknut uskrisio od smrti na život brata joj Lazara, koji je već četiri dana ležao u grobu:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Da nas porhognu. Gospodine, zagovori blažene Marije Magdalene, kojoj si uslišao molbe i brata Lazara nakon četiri dana živa o>d mrtvih uskrisio, koji živiš . . .","knRef":"Kniewald 1942, str. 648–649 (snimka 325) (OCR)"},"7ed35efd109c957f":{"t":"Pj 3, 2-5; 8, 6-7\nČitanje knjige Mudrosti. Ustat ću i obilaziti gradom tražeći po putovima i trgovima onoga kojega ljubi moja duša. Tražila sam ga, ali ga nisam našla. Sreli me stražari koji čuvaju grad i pitam: Jeste li vidjeli onoga kojega ljubi moja duša? Kada sam se malo udaljila od njih, eno mi ususret onoga kojega ljubi moja duša. Držim ga i ne puštam dok ga ne uvedem u dom svoje majke i u stan svoje roditeljice. Zaklinjem vas, jeruzalemske kćeri, srnama i košutama na livadama: Ne smetajte i ne budite moje ljubljene dok ona sama ne htjedne, jer je ljubav jaka kao smrt, a ljubomora kruta kao pakao. Njezin žar pali kao oganj i buktinja. Velika voda ne može ugasiti ljubav niti je sve rijeke mogu ugasiti. Kada bi tko radi ljubavi dao sve bogatstvo svojega doma, prezreo bi ga!","kn":".Čitanje Knjige mudrosti (Rj'esma nad pjesmama, 3, 2-5; 8, 6-7). Ustat ću i obilaziti gradom, tražit ću po iRUtevima' ^ i trgovima,^ koga ljubi moja duša. Tražila sam ga, ali ga ne nađO'h. Sreli su me stra- žaTi,- koji čuvaju grad; Daj U ste vidjeli, koga ljubi moja duša? Kad se malo udaljih od njih, nađoh onoga, koga ljubi molja duša. Uhvatila sam ga^ 1 ne ću ga pustiti, dok ga ne uvedem u dom svoje majke,'* i u sobu svoje roditeljice. Zaklinjem vas, Jeruzailem.ske kćeri, srnama i jelenima u polju, da ne bunite i ne budite ljubljenu, dok ona ne htjedne, jer je ljubav Jaka kao smrt, a IjubomOT tvrd kao pakao. Njezin žar je plamen ognja i buktinja. Mnogo vode ne može ugasiti ljubavi niti je potopiti rijeke. Kad bi ‘tko dao sve bogatstvo svoga doma, prozreo bi ga kao ništa radi ljubavi.","knRef":"Kniewald 1942, str. 648–649 (snimka 325) (OCR)"},"be1e39e161f3c070":{"t":"Ps 44, 8\nLjubiš pravdu a mrziš nepravdu. Zato te je pomazao Bog, Bog tvoj, uljem radosti.\n\nPs 44, 3\n<i>Aleluja</i>, <i>aleluja</i>.\nRazlita je milina na usnama tvojim. Zbog toga te je Bog blagoslovio u vijeke. <i>Aleluja</i>.","kn":"(Ps, 44, 8). Ti ljubiš pravdu i mrziš nepravdu, zato te pomazao Gospodin Bog tvoj uljem radosti.\n\nAleluja, aleluja (Ps. 44, 3). Milost se razlila usnama tvojim, zato te Bog blagoslovio zauvijek, aleluja.","knRef":"Kniewald 1942, str. 650–651 (snimka 326) (OCR)"},"e5f50f95a3c0903d":{"t":"Lk 7, 36-50\nSlijedi sveto Evanđelje po Luki. U ono vrijeme neki farizej pozove Isusa na gozbu. Uđe u farizejevu kuću, sjedne za stol, a neka grješnica, kada je doznala da je za stolom u farizejevoj kući, dođe, donese sobom alabastrovu posudu pomasti, stane iza njega do njegovih nogu, poče plakati, suzama mu prati noge, otirati ih svojom kosom, ljubiti ih i mazati ih pomašću. Kada to vidi farizej koji ga je pozvao, pomisli: Da je ovaj prorok, znao bi tko i kakva je žena koja ga se dotiče: da je grješnica. Isus mu reče: Šimune, imam ti nešto kazati. On odgovori: Kaži, Učitelju! Isus reče: Imao je vjerovnik dva dužnika. Jedan je dugovao petsto dinara, a drugi pedeset. On oprosti obojici, jer nisu mogli vratiti. Koji će ga od one dvojice više ljubiti? Šimun odgovori: Mislim onaj kojemu je više oprostio. Isus mu reče: Ispravno si sudio. Pokazujući na ženu upita Šimuna: Vidiš li ovu ženu? Ušao sam u tvoju kuću, nisi mi polio noge vodom, a ona mi je suzama oprala noge i otrla ih svojom kosom. Nisi mi dao poljupca, a ona otkad uđe, ne prestaje cjelivati mojih nogu; nisi mi glave namazao uljem, a ona mi je noge pomazala miomirisnom pomasti. Zato ti kažem: Njoj se opraštaju mnogi grijesi, jer je ljubila mnogo. Kome se manje oprašta, ljubi manje. A ženi reče: Oprošteni su ti grijesi! I oni, koji su sjedili za stolom s njim, pitali su se u sebi: Tko je ovaj da oprašta grijehe? Tada reče ženi: Spasila te tvoja vjera. Idi u miru!","kn":"t Slijedi sv. evanđelje po Luki (7, 36-50). U ono je vrijeme molio Isusa jedan od farizeja, da bi jeo s njim. I ušavši u kuću farizejsku, sjede za stol. I gle, žena, koja je bila griješnica u gradu, doznavši, da je on za stolom u kući farizejevoj, donese posudicu od alabastra s pomasti. I stavi straga kod nogu njegovih, plačući stade suzama prati noge njegove i kosom s glave svoje otare ih, te je cjelivala noge njegove i pomasti mazala. Kad to vidje farizej, koji ga je pozvao, pomisli u sebi: Da je ovo prorok, znao bi dakako, tko i kakva je žena, koja ga se dotiče, da je grješnica. Tada prozbori Isus i reče mu: Simune, imam ti nešto kazati. On reče; Učitelju, kaži! Dvojica su bili dužni jednome vje- rovniku; jedan je bio dužan pet stotina dinara, a drugi pedeset. A kad oni ne imadoše, odakle da vrate, pokloni obojici. Koji će ga dakle od njih više ljubiti? Odgovori Simun: Mislim, da onaj, komn je više poklonio. On mu reče: Pravo si sudio. I okrenuvši se k ženi, reče Simunu: Vidiš li ovu ženu?Uđoh u tvoju kuću, vode mi na noge nisi dao, a ova suzama obli moje noge i svojom kosom otare. C jelova mi nisi dao; a ova, otkako uđe, ne presta cjelivati nogu mojih. Uljem nisi pomazao glave moje, a ona pomašću pomaza noge moje. Zato ti kažem; Oprošteni su joj mnogi grijesi; jer je mnogo ljubila; a kome se manje prašta, manje ljubi. A njoj reče; Oprošteni su ti grijesi. I stadoše misliti u sebi oni, što su sjedili s njime za stolom: Tko je ovaj, da i grijehe oprašta? A ženi reče: Vjera ti je tvoja pomogla, idi u miru!","knRef":"Kniewald 1942, str. 206–207 (snimka 104) (OCR)"},"3ef3e3394cd6d09a":{"t":"Ps 44, 10\nKraljevske kćeri dolaze ti ususret, Kraljica stoji uz desnu tvoju ogrnuta presjajnom zlatnom haljinom.","kn":"(Ps. 44, 16). Pratit će te kćeri kraljevske: z desne tvoje sama kraljica, ogrnuta presjajnom zlatnom haljinom.","knRef":"Kniewald 1942, str. 826–827 (snimka 414) (OCR)"},"03c801ac0806271e":{"t":"Molimo, Gospodine, da ti naše darove učine ugodnima slavne zasluge blažene Marije Magdalene, čiju je požrtvovnu službu rado primio tvoj jedinorodeni Sin:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Slavne zasluge svete Marije Magdalene učinile Tebi, Grospodine, ugodnima naše. darove, jer je ^ Tvoj jedinorođenl Sin milo primio žrtvovani prinofS n.j&zln© službe; koji s Tobom živi .","knRef":"Kniewald 1942, str. 652–653 (snimka 327) (OCR)"},"404159d2e4df1ef4":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. – Po njemu tvoje veličanstvo hvale anđeli, klanjaju se gospodstva i dršću vlasti. Nebesa i nebeske sile i blaženi serafini zajedničkim klicanjem slave. Daj, molimo, s njima i naše glase primi dok govorimo poniznim hvalospjevom:","kn":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospotdiniu našemu, po kome veličanstvo Tvoje hvale anđeli, klanjaju Ti se gospodstva, tresu se vlasti. Nebesa Te i nebeske moći i blaženi serafini, zadružnim klicanjem zajedno slave. Zapovijedi, molimo, da se i naši glasovi združe s njihovima, smjernim isippvijedanjem govoreći:","knRef":"Kniewald 1942, str. 18–19 (snimka 10) (OCR)"},"85c6faa6661f99fa":{"t":"Ps 118, 121 i 122 i 128\nČinim što je dobro i pravo, Gospodine. Ne daj da me ozloglase oholi. Držim se tvojih zapovijedi, a mrzim svaki nevaljali put.","kn":"(Ps. 118, 121, 128). Ja činim, što je pravo pred Tobom, Gospodine, ne daj, da me upropaste oholi; znam, pravedna je svaka Tvoja odredba., ja mrzim put nepravde.","knRef":"Kniewald 1942, str. 824–825 (snimka 413) (OCR)"},"37943f1412fd6003":{"t":"<i>Pomolimo se</i>.\nPošto smo primili, Gospodine, jedini i spasonosni lijek, dragocjeno tvoje tijelo i krv, molimo, da se po zaštiti svete Marije Magdalene oslobodimo od svih zala:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Primivši, Gospodine, jedini i spasonosni lijek. Tvoje dragocjeno tijelo i- Tvoju dragocjenu krv, molimo, da nas zaštita svete Marije Magdalene izbavi od svih zala; koji živiš .i kra- Ijuješ ...","knRef":"Kniewald 1942, str. 652–653 (snimka 327) (OCR)"}}});
